import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, Router } from '@angular/router';
import { AuthService } from '../../core/auth.service';

declare const document: any;
declare const sessionStorage: any;

interface Tier { id: number; label: string; price: number; }
interface Group { title: string; tiers: Tier[]; note?: string; }
interface CategoryTab { key: string; label: string; groups: Group[]; }

// TODO: replace placeholder ids (1xx/2xx) with the real plan IDs from your `plans` table.
const CATEGORIES: CategoryTab[] = [
  {
    key: 'musculation', label: 'Musculation',
    groups: [
      { title: 'MEMBERSHIP', tiers: [
        { id: 101, label: '1 Month', price: 90 },
        { id: 102, label: '2 Months', price: 160 },
        { id: 103, label: '3 Months', price: 180 },
        { id: 104, label: '6 Months', price: 340 },
        { id: 105, label: '12 Months', price: 700 },
      ]},
      { title: 'PRIVATE COACHING', tiers: [
        { id: 106, label: '1 Session', price: 30 },
        { id: 107, label: '8 Sessions', price: 200 },
        { id: 108, label: '16 Sessions', price: 320 },
        { id: 109, label: 'Drop-in floor session', price: 10 },
      ]},
    ],
  },
  {
    key: 'pilates', label: 'Pilates',
    groups: [
      { title: 'REFORMER — ESSENTIEL', tiers: [
        { id: 201, label: '8 sessions · 30 days', price: 260 },
        { id: 202, label: '12 sessions · 45 days', price: 360 },
        { id: 203, label: '24 sessions · 90 days', price: 550 },
        { id: 204, label: '48 sessions · 180 days', price: 1050 },
      ]},
      { title: 'REFORMER + PRIVÉ — PREMIUM', tiers: [
        { id: 205, label: '5R + 3P · 30 days', price: 290 },
        { id: 206, label: '7R + 5P · 45 days', price: 420 },
        { id: 207, label: '16R + 8P · 90 days', price: 750 },
        { id: 208, label: '38R + 10P · 180 days', price: 1300 },
      ]},
      { title: 'PILATES + MUSCULATION — INTÉGRAL', tiers: [
        { id: 209, label: '1 Month · 8 R', price: 320 },
        { id: 210, label: '3 Months · 24 R', price: 700 },
        { id: 211, label: '6 Months · 48 R', price: 1350 },
        { id: 212, label: '12 Months · 100 R', price: 2650 },
      ]},
      { title: 'PRIVATE SESSIONS', note: 'R = Reformer  P = Privé (Cadillac, Wunda Chair, Barrel, Tower)', tiers: [
        { id: 213, label: 'Reformer', price: 35 },
        { id: 214, label: 'Private (any machine)', price: 45 },
        { id: 215, label: '8 Private sessions', price: 340 },
      ]},
    ],
  },
];

@Component({
  selector: 'app-select-plan',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './plan.component.html',
  styleUrl: './plan.component.css'
})
export class PlanComponent implements OnInit {
  categories = CATEGORIES;
  activeCategory: CategoryTab = CATEGORIES[0];
  selected: number | null = null;
  error = '';
  loading = false;

  constructor(private auth: AuthService, private router: Router) {}

  ngOnInit(): void {
    const saved = sessionStorage.getItem('signup_category');
    const match = CATEGORIES.find(c => c.key === saved);
    if (match) this.activeCategory = match;
  }

  setCategory(cat: CategoryTab): void {
    this.activeCategory = cat;
    this.selected = null;
    this.error = '';
  }

  select(id: number): void {
    this.selected = id;
    this.error = '';
  }

  async confirm(): Promise<void> {
    if (!this.selected) {
      this.error = 'Please select a plan';
      return;
    }
    const btn = document.getElementById('plan-continue');
    btn?.classList.add('auth-form__submit--loading');
    btn.disabled = true;
    this.loading = true;

    try {
      await this.auth.setSubscription(this.activeCategory.key, this.selected); // POST /api/auth/subscription
      sessionStorage.removeItem('signup_category');
      this.router.navigate(['/pending']);
    } catch (err: any) {
      this.error = err?.error?.error || 'Something went wrong, please try again';
    } finally {
      btn?.classList.remove('auth-form__submit--loading');
      btn.disabled = false;
      this.loading = false;
    }
  }
}
<div class="auth-body">
<div class="auth">
  <div class="auth__visual" id="auth-visual">
    <div class="auth__scrim"></div>
    <div class="auth__visual-content">
      <a class="auth__brand" routerLink="/"><img src="assets/logo.svg" alt="EOS" height="25" style="display:block;"></a>
      <div class="auth__caption">
        <p class="auth__caption-eyebrow">Last step</p>
        <h2>Pick your membership</h2>
        <p>Choose the plan that fits your goals.</p>
      </div>
    </div>
  </div>

  <div class="auth__panel">
    <div class="auth__navbar">
      <a class="auth__navbar-brand" routerLink="/"><img src="assets/logo.svg" alt="EOS"></a>
    </div>

    <div class="auth__panel-scroll">
    <div class="auth__card">
      <div class="auth__head">
        <h1>Choose your plan</h1>
        <p>Membership is activated once the admin approves your account</p>
      </div>

      <div class="plan-list" *ngIf="!loading">
        <button type="button" class="plan-card"
                *ngFor="let p of plans"
                [class.plan-card--active]="selected === p.id"
                (click)="select(p.id)">
          <span class="plan-card__info">
            <span class="plan-card__name">{{ p.name }} — {{ p.duration_months }} mo</span>
            <span class="plan-card__quota">{{ p.classes_per_month ? p.classes_per_month + ' classes/mo' : 'Unlimited classes' }}</span>
          </span>
          <span class="plan-card__price">{{ p.price }} TND</span>
        </button>
      </div>

      <span class="field__error" [class.field__error--show]="error">{{ error }}</span>

      <button type="button" class="auth-form__submit" id="plan-continue" (click)="confirm()" [disabled]="loading">
        <svg class="spinner" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><path d="M21 12a9 9 0 1 1-9-9"/></svg>
        <span class="btn-label">Confirm & Submit</span>
      </button>
    </div>
    </div>
  </div>
</div>
</div>
